'use strict';

// MODULES //

var besselj1 = require( '@stdlib/math/base/special/besselj1' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// MAIN //

/**
* Computes the Bessel function of the first kind of order one for a single-precision floating-point number.
*
* @param {number} x - input value
* @returns {number} evaluated Bessel function
*
* @example
* var v = besselj1f( 0.0 );
* // returns 0.0
*
* @example
* var v = besselj1f( 1.0 );
* // returns ~0.440
*
* @example
* var v = besselj1f( Infinity );
* // returns 0.0
*
* @example
* var v = besselj1f( NaN );
* // returns NaN
*/
function besselj1f( x ) {
	return f32( besselj1( f32( x ) ) );
}


// EXPORTS //

module.exports = besselj1f;
